/*
 * A348437  Where n appears for the first time in A088177.
 * https://oeis.org/A348437
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = least k such that A088177(k) = n; A088177 is generated by
 *            search (a(1)=a(2)=1, then smallest a(n) making adjacent products
 *            distinct)
 * Range:     u8 n <= 21, u16 n <= 399, u32 n <= 500, u64 n <= 500,
 *            u128 n <= 500, big any n
 * Validated: standard, pass, 80 terms through n = 445 (2026-11-10)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/mem.h"

static seq_t *A348437_seq = NULL;
static size_t A348437_cap = 0;
static size_t A348437_len = 0;

static seq_t *A348437_tab = NULL;
static size_t A348437_mask = 0;
static size_t A348437_cnt = 0;

static size_t A348437_hash(seq_t x)
{
    uint64_t h = (uint64_t)(unsigned long long)(x % (seq_t)4294967291u);
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdULL;
    h ^= h >> 33;
    h *= 0xc4ceb9fe1a85ec53ULL;
    h ^= h >> 33;
    return (size_t)h;
}

static bool A348437_contains(seq_t v)
{
    size_t pos = A348437_hash(v) & A348437_mask;
    while (A348437_tab[pos] != 0) {
        if (A348437_tab[pos] == v) return true;
        pos = (pos + 1) & A348437_mask;
    }
    return false;
}

static void A348437_insert(seq_t v)
{
    if ((A348437_cnt + 1) * 10 > (A348437_mask + 1) * 7) {
        size_t oc = A348437_mask + 1, nc = oc * 2, nm = nc - 1;
        seq_t *nt = mem_new(seq_t, nc);
        for (size_t i = 0; i < oc; ++i) {
            seq_t w = A348437_tab[i];
            if (w == 0) continue;
            size_t p = A348437_hash(w) & nm;
            while (nt[p] != 0) p = (p + 1) & nm;
            nt[p] = w;
        }
        mem_free(A348437_tab);
        A348437_tab = nt;
        A348437_mask = nm;
    }
    size_t pos = A348437_hash(v) & A348437_mask;
    while (A348437_tab[pos] != 0) pos = (pos + 1) & A348437_mask;
    A348437_tab[pos] = v;
    ++A348437_cnt;
}

static void A348437_push(seq_t v)
{
    if (A348437_len + 1 > A348437_cap) {
        size_t nc = A348437_cap ? A348437_cap * 2 : 64;
        A348437_seq = mem_resize(seq_t, A348437_seq, nc);
        A348437_cap = nc;
    }
    A348437_seq[A348437_len++] = v;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;
    if (!A348437_tab) {
        A348437_mask = 63;
        A348437_tab = mem_new(seq_t, 64);
        A348437_cnt = 0;
        A348437_push((seq_t)1);
        A348437_push((seq_t)1);
        A348437_insert((seq_t)1);
    }
    seq_t target = (seq_t)n;
    for (size_t i = 0; i < A348437_len; ++i)
        if (A348437_seq[i] == target) return (seq_t)(i + 1);
    for (;;) {
        seq_t prev = A348437_seq[A348437_len - 1];
        seq_t cur = (seq_t)1;
        seq_t prod;
        for (;;) {
            prod = prev * cur;
            if (!A348437_contains(prod)) break;
            ++cur;
        }
        A348437_insert(prod);
        A348437_push(cur);
        if (cur == target) return (seq_t)A348437_len;
    }
}
